"""Türkçe — erdemler (virtues_001 … virtues_050)."""

T = {
"virtues_001": ("İmam Buhârî'nin rivayet ettiği bir hadise göre Allah'a ve ahiret gününe inanan kişi sözleriyle ne yapmalıdır?", ["Ya hayır söylemeli ya susmalı", "Yüksek sesle konuşmalı", "Hiç konuşmamalı", "Söylentileri tekrarlamalı"], "Peygamber ﷺ dedi ki: «Allah'a ve ahiret gününe inanan ya hayır söylesin ya sussun.»"),
"virtues_002": ("Aynı hadise göre mümin, misafirinin yanı sıra kime ikramda bulunmalıdır?", ["Komşusuna", "Tüccarına", "Rakibine", "Bir yabancıya"], "Hadis şöyle devam eder: «…Allah'a ve ahiret gününe inanan komşusuna ikram etsin.»"),
"virtues_003": ("Aynı hadis, evine geldiğinde kime ikram etmeyi de anar?", ["Misafire", "Yalnızca komşuya", "Tüccara", "Uzak, tanınmayan bir yolcuya"], "Hadisin tamamı: «…Allah'a ve ahiret gününe inanan misafirine ikram etsin.»"),
"virtues_004": ("Sahih bir hadise göre bir mümin, kendisi için sevdiğini kardeşi için de sevmedikçe imanı tamam olmaz. Neyi?", ["Kendisi için sevdiğini", "Malını", "Yalnızca ailesini", "Ülkesini"], "Peygamber ﷺ dedi ki: «Hiçbiriniz kendisi için sevdiğini kardeşi için de sevmedikçe gerçekten iman etmiş olmaz.»"),
"virtues_005": ("Sahih bir hadise göre gerçek Müslüman, dilinden ve ___ başkalarının güvende olduğu kişidir.", ["Elinden", "Malından", "Bakışından", "Sesinden"], "Peygamber ﷺ dedi ki: «Müslüman, diğer Müslümanların elinden ve dilinden güvende olduğu kişidir.»"),
"virtues_006": ("Kur'an anne babaya iyiliği emreder ve onlara hangi bezginlik sözünü bile söylemeyi yasaklar?", ["«Öf» (sabırsızlık sesi)", "«Hayır»", "«Yeter»", "«Bekle»"], "Kur'an anne babaya en üst düzeyde iyilik ister; en küçük hor görme sözünü bile yasaklar."),
"virtues_007": ("Kur'an gıybeti (arkasından kötü konuşmayı) neye benzetir?", ["Ölmüş kardeşinin etini yemeye", "Tuzlu su içmeye", "Karanlıkta yürümeye", "Kuma ekmeye"], "«Biriniz ölmüş kardeşinin etini yemek ister mi? Bundan tiksinirsiniz!»: gıybet işte bu kadar çirkindir."),
"virtues_008": ("Kur'an müminler arasındaki ilişkiyi nasıl tanımlar?", ["Kardeştirler", "Rakiptirler", "Yabancıdırlar", "İş ortağıdırlar"], "«Müminler ancak kardeştirler; öyleyse iki kardeşinizin arasını düzeltin.»"),
"virtues_009": ("Kur'an başkalarıyla alay etmek hakkında ne der?", ["Yasaktır: alay edilenler edenlerden daha hayırlı olabilir", "Arkadaşlar arasında serbesttir", "Komikse serbesttir", "Şairlere mahsustur"], "«Bir topluluk diğeriyle alay etmesin; belki onlar kendilerinden daha hayırlıdır.»"),
"virtues_010": ("Kur'an'a göre Allah şükredene ne vaat eder?", ["Nimetini artıracağını", "Uzun ömür", "Hemen zenginlik", "Bir yolculuk"], "«Şükrederseniz elbette size daha fazlasını veririm.»"),
"virtues_011": ("Kur'an'a göre sabredenler mükâfatlarını nasıl alacak?", ["Hesapsız, tam olarak", "Hepsini bir kerede", "Kırk gün sonra", "Servetlerine göre"], "«Sabredenlere mükâfatları hesapsız verilir.»"),
"virtues_012": ("«Yiyin, için, ama…»: bu ayet nasıl devam eder?", ["İsraf etmeyin", "Paylaşmayın", "Konuşmayın", "Dışarı çıkmayın"], "«Yiyin, için, fakat israf etmeyin: Allah israf edenleri sevmez.»"),
"virtues_013": ("Cuma hutbesinde sık okunan hangi ayet Allah'ın emrettiklerini özetler?", ["«Allah adaleti ve iyiliği emreder»", "«Allah ticareti emreder»", "«Allah yolculuğu emreder»", "«Allah susmayı emreder»"], "«Allah adaleti, iyiliği ve akrabaya vermeyi emreder…»: her cuma okunur."),
"virtues_014": ("Mutaffifîn suresi kimlere karşı «Yazıklar olsun…» diye başlar?", ["Ölçü ve tartıda hile yapanlara", "Uyuyanlara", "Yolculara", "Susanlara"], "«Ölçüde ve tartıda hile yapanlara yazıklar olsun: alırken tam alır, verirken eksik verirler!»"),
"virtues_015": ("Duhâ suresine göre yetime ve isteyene nasıl davranılmalıdır?", ["Ne ezilmeli ne azarlanmalı", "Görmezden gelinmeli", "Başkalarına gönderilmeli", "Sonra konuşulmalı"], "«Yetimi ezme; isteyeni de azarlama.»"),
"virtues_016": ("Kur'an insanlara nasıl konuşmayı emreder?", ["Güzel söz söylemeyi", "Çok alçak sesle", "Olabildiğince az", "Yalnızca akrabalara"], "«…ve insanlara güzel söz söyleyin»: güzel söz başlı başına ibadettir."),
"virtues_017": ("Lokman oğluna öğütlerinde yürüyüş ve kibir hakkında ne der?", ["Yeryüzünde böbürlenerek yürüme", "Her zaman hızlı yürü", "Yalnızca gece yürü", "Asla yalnız yürüme"], "«İnsanlardan yüzünü kibirle çevirme ve yeryüzünde böbürlenerek yürüme.»"),
"virtues_018": ("Buhârî'nin derlemesinin ilk hadisine göre ameller neye bağlıdır?", ["Niyetlere", "Sonuçlara", "Alışkanlıklara", "Şahitlere"], "«Ameller ancak niyetlere göredir ve herkes için ancak niyet ettiği vardır.»"),
"virtues_019": ("Buhârî'deki bir hadise göre doğruluk (sıdk) nereye götürür?", ["İyiliğe, iyilik de cennete götürür", "Zenginliğe", "Şöhrete", "Güce"], "«Doğruluk iyiliğe, iyilik cennete götürür; yalan kötülüğe, kötülük ateşe götürür.»"),
"virtues_020": ("Sahih bir hadise göre münafığın üç alameti nedir?", ["Konuşunca yalan söyler, söz verince tutmaz, emanete hıyanet eder", "Çok uyur, çok yer, çok konuşur", "Seyahat eder, ticaret yapar, şarkı söyler", "Az namaz kılar, az oruç tutar, az okur"], "«Münafığın alameti üçtür: konuştuğunda yalan söyler, söz verdiğinde tutmaz, emanet edildiğinde hıyanet eder.»"),
"virtues_021": ("Bir adam Peygamber ﷺ'den öğüt istedi; Peygamber ona neyi birkaç kez tekrarladı?", ["«Kızma»", "«Çok seyahat et»", "«Az ye»", "«Yüksek sesle konuş»"], "Adam «Bana öğüt ver» dedi. «Kızma» dedi. Adam tekrar sordu, yine «Kızma» dedi."),
"virtues_022": ("Peygamber ﷺ'e göre gerçekten güçlü olan kimdir?", ["Öfkelendiğinde kendine hâkim olan", "Güreşte yenen", "En ağır yükleri taşıyan", "En hızlı koşan"], "«Güçlü, güreşte yenen değildir; güçlü, öfkelendiğinde kendine hâkim olandır.»"),
"virtues_023": ("Buhârî'deki bir hadise göre hayâ neyin bir parçasıdır?", ["İmanın", "Zayıflığın", "Zenginliğin", "Kınanan çekingenliğin"], "Peygamber ﷺ, kardeşini hayâsı yüzünden azarlayan bir adama «Bırak onu, hayâ imandandır» dedi."),
"virtues_024": ("On çocuğundan hiçbirini öpmemekle övünen bir adama Peygamber ﷺ ne dedi?", ["«Merhamet etmeyene merhamet edilmez»", "«Haklısın»", "«Çocuklar önemli değil»", "«Bu özel bir mesele»"], "Peygamber ﷺ torunlarını öperdi; şaşıran Akra'ya «Men lâ yerham lâ yurham» dedi."),
"virtues_025": ("Buhârî'deki bir hadise göre bir adam hangi işi yüzünden bağışlandı?", ["Susamış bir köpeğe su verdiği için", "Bir kuyu kazdığı için", "Bir ağaç diktiği için", "Bir kurdu kovduğu için"], "Adam kuyuya indi, ayakkabısını suyla doldurdu ve susuzluktan soluyan köpeğe içirdi; Allah onu bağışladı."),
"virtues_026": ("Sahih bir hadise göre bir kadın neden azaba uğradı?", ["Bir kediyi beslemeden ve yiyecek aramasına izin vermeden hapsettiği için", "Bir kedi sattığı için", "Bir kediyi evinden kovduğu için", "Çok fazla kedi sahiplendiği için"], "«Bir kadın, ölene kadar hapsettiği bir kedi yüzünden azaba uğradı: ne onu besledi ne de yeryüzünün haşeratından yemesine izin verdi.»"),
"virtues_027": ("Peygamber ﷺ, Cebrail'in kendisine kimi o kadar tavsiye ettiğini söyledi ki onu mirasçı yapacağını sandı?", ["Komşuyu", "Misafiri", "Yetimi", "Yolcuyu"], "«Cebrail bana komşuyu öyle tavsiye etti ki onu mirasçı kılacak sandım.»"),
"virtues_028": ("Buhârî'deki bir hadise göre Müslümanın Müslüman kardeşi üzerinde kaç hakkı vardır?", ["Beş", "Üç", "Yedi", "On"], "«Selamı almak, hastayı ziyaret etmek, cenazeye katılmak, davete icabet etmek ve aksırana dua etmek.»"),
"virtues_029": ("«Hangi İslam daha hayırlıdır?» sorusuna Peygamber ﷺ ne cevap verdi?", ["Yemek yedirmek, tanıdığına ve tanımadığına selam vermek", "Mescit yapmak", "Çok seyahat etmek", "Az konuşmak"], "«Yemek yedirmen ve tanıdığına da tanımadığına da selam vermendir.»"),
"virtues_030": ("Peygamber ﷺ müminleri sevgi ve dayanışmalarında neye benzetir?", ["Tek bir bedene: bir uzvu ağrısa bütün beden uykusuzluk ve ateşle ona katılır", "Bir ormana", "Bir kervana", "Bir sürüye"], "«Müminler birbirlerini sevmede, merhamette ve şefkatte tek bir beden gibidir.»"),
"virtues_031": ("Peygamber ﷺ'e göre «sözün en yalanı» nedir?", ["Zan (kuruntu)", "Şiir", "Şaka", "Sessizlik"], "«Zandan sakının, çünkü zan sözün en yalanıdır.»"),
"virtues_032": ("Sahih bir hadise göre bir Müslüman kardeşine en fazla kaç gün küs kalabilir?", ["Üç gün", "Yedi gün", "Bir ay", "Bir yıl"], "«Bir kimsenin kardeşine üç geceden fazla küs kalması helal değildir… ikisinin en hayırlısı önce selam verendir.»"),
"virtues_033": ("Peygamber ﷺ'e göre ne kadar küçük olursa olsun her iyiliğin değeri nedir?", ["Sadakadır", "Sayılmaz", "Bir dinar eder", "Namazın yerine geçer"], "«Her iyilik sadakadır.»"),
"virtues_034": ("Sahih-i Müslim'deki bir hadise göre imanın en alt şubesi nedir?", ["Yoldan eziyet veren şeyi kaldırmak", "Mescit yapmak", "Bir cüz okumak", "Bir gün oruç tutmak"], "«İman yetmiş küsur şubedir: en üstünü ‘lâ ilâhe illallah’ demek, en altı yoldan eziyet veren şeyi kaldırmaktır; hayâ da imanın bir şubesidir.»"),
"virtues_035": ("Sahih-i Müslim'deki bir hadise göre temizlik (tahâret) …", ["İmanın yarısıdır", "İmanın üçte biridir", "İmanın onda biridir", "İmanla ilgisizdir"], "«Temizlik imanın yarısıdır ve ‘elhamdülillah’ mizanı doldurur.»"),
"virtues_036": ("Peygamber ﷺ «Din nasihattir» dedi. Kime karşı?", ["Allah'a, Kitabına, Resulüne, yöneticilere ve bütün Müslümanlara", "Yalnızca kendine", "Zenginlere", "Yabancılara"], "«Kime?» diye sordular. «Allah'a, Kitabına, Resulüne, Müslümanların yöneticilerine ve hepsine» dedi."),
"virtues_037": ("Sahih-i Müslim'deki bir hadise göre Allah kullarında neye bakar?", ["Kalplerine ve amellerine", "Görünüşlerine", "Servetlerine", "Sayılarına"], "«Allah bedenlerinize ve suretlerinize bakmaz; kalplerinize ve amellerinize bakar.»"),
"virtues_038": ("Sahih-i Müslim'deki bir hadise göre bir müminin dünya sıkıntısını gideren kişiye Allah ne yapar?", ["Kıyamet günü sıkıntılarından birini giderir", "Onu zengin eder", "Ona uzun ömür verir", "Onu meşhur eder"], "«Kim bir müminin dünya sıkıntılarından birini giderirse Allah da onun kıyamet günü sıkıntılarından birini giderir.»"),
"virtues_039": ("Peygamber ﷺ'e göre ilim aramak için yola çıkana Allah ne yapar?", ["Ona cennete giden bir yolu kolaylaştırır", "Onu namazdan muaf tutar", "Onu zengin eder", "Onu kral yapar"], "«Kim ilim aramak için bir yola girerse Allah ona cennete giden bir yolu kolaylaştırır.»"),
"virtues_040": ("Buhârî'deki bir hadise göre «en hayırlınız» kimdir?", ["Kur'an'ı öğrenen ve öğreten", "En güzel konuşan", "En çok mala sahip olan", "En çok seyahat eden"], "«En hayırlınız Kur'an'ı öğrenen ve öğreteninizdir.»"),
"virtues_041": ("Peygamber ﷺ kibri nasıl tanımladı?", ["Hakkı kabul etmemek ve insanları küçük görmek", "Güzel giysi giymek", "Güzel ayakkabı sevmek", "Hızlı yürümek"], "Güzel giysi seven adama dedi ki: «Allah güzeldir, güzelliği sever. Kibir, hakkı kabul etmemek ve insanları küçük görmektir.»"),
"virtues_042": ("Buhârî'deki bir hadise göre birçok insanın değerini bilmediği iki nimet hangileridir?", ["Sağlık ve boş vakit", "Para ve şöhret", "Güç ve güzellik", "Aile ve dostlar"], "«İki nimet vardır ki insanların çoğu onlarda aldanmıştır: sağlık ve boş vakit.»"),
"virtues_043": ("Bu hadisi tamamla: «Mümin iki kez sokulmaz…»", ["«…aynı delikten»", "«…aynı akrep tarafından»", "«…aynı günde»", "«…aynı arı tarafından»"], "«Lâ yüldeğu'l-mü'minü min cuhrin vâhidin merrateyn»: mümin hatalarından ders alır."),
"virtues_044": ("Peygamber ﷺ iyi arkadaşı, demirciye karşılık neye benzetir?", ["Misk satıcısına", "Fırıncıya", "Çobana", "Kumaş tüccarına"], "«İyi arkadaş misk taşıyan gibidir: ya sana verir, ya ondan satın alırsın, ya da güzel kokusunu duyarsın; kötü arkadaş demircinin körüğü gibidir.»"),
"virtues_045": ("Buhârî'deki bir hadise göre her birimiz «bir çoban gibi» neyden sorumluyuz?", ["Sorumluluğumuzdakilerden", "Havadan", "Yıldızlardan", "Başkalarının hasadından"], "«Hepiniz çobansınız ve hepiniz sürünüzden sorumlusunuz»: yönetici halkından, erkek ailesinden, kadın evinden."),
"virtues_046": ("Kur'an'a göre kötülük en güzel şekilde savılırsa ne olur?", ["Düşman olan kişi sıcak bir dost gibi olur", "Kötülük yeryüzünden kalkar", "İnsan zengin olur", "Hiçbir şey değişmez"], "«Kötülüğü en güzel şekilde sav; o zaman aranızda düşmanlık olan kişi sanki sıcak bir dost olur» (41:34)."),
"virtues_047": ("Furkan suresine göre «Rahman'ın kulları» kendilerini kışkırtan cahillere nasıl cevap verir?", ["«Selam!» derler", "Öfkeyle cevap verirler", "Onlarla alay ederler", "Onlara vururlar"], "«Rahman'ın kulları yeryüzünde alçakgönüllülükle yürürler; cahiller onlara laf attığında ‘selam’ derler» (25:63)."),
"virtues_048": ("Kur'an ahit (söz, antlaşma) hakkında ne der?", ["«Ahdi yerine getirin, çünkü ahitten sorulacaktır»", "«Söz kimseyi bağlamaz»", "«Yalnızca zenginlere söz verin»", "«Asla söz vermeyin»"], "«Ahdi yerine getirin; şüphesiz ahitten sorulacaktır» (17:34)."),
"virtues_049": ("Kur'an kimler için «şeytanların kardeşleri» der?", ["Saçıp savuranlar için", "Yolcular için", "Tüccarlar için", "Şairler için"], "«Saçıp savuranlar şeytanların kardeşleridir; şeytan ise Rabbine karşı çok nankördür» (17:27)."),
"virtues_050": ("«Dile hafif, mizanda ağır, Rahman'a sevimli iki kelime» nedir?", ["«Sübhanallahi ve bihamdihi, sübhanallahi'l-azim»", "«Allahu ekber, elhamdülillah»", "«Lâ ilâhe illallah, Muhammedün resûlullah»", "«Bismillah, mâşâallah»"], "«Dile hafif, mizanda ağır, Rahman'a sevimli iki kelime: Sübhanallahi ve bihamdihi, sübhanallahi'l-azim.»"),
}
